# 41g_profess_trust_lag.R
# Lagged correlation: professionalisation IV vs political trust
#
# Trust DV: BSA "trust govt just about always/most of time", extended
#   1979-2025 via TrustGov/Ipsos calibration for BSA gap years
#   (trust_extended_1979_2025.csv — see 41k/41l, sources_raw/trustgov_dataset/,
#   sources_raw/ipsos_veracity_index/). ~24 years genuinely BSA-observed,
#   ~23 years calibrated (TrustGov 1979-2020 gaps, Ipsos 2021/22/25) — figures
#   below distinguish observed vs. calibrated points, do not blend them silently.
# IV: professionalisation PC1 from 41e (career politicians, SPADs, staffing)
#   1979-2023
#
# Figure 1: time series overlay (both Z-scored, 1990-2023)
# Figure 2: scatter plots at lag 0, 1, 2
#
# NOTE: both series are time-trended (prof up, trust down) — correlations
# are informative about association but not causal identification.
# Caution: trust is a Ch4 (political culture) variable; this script explores
# the cross-chapter link professionalisation → trust, not the Ch4 main analysis.
#
# OUTPUTS:
#   figures/ch3_profess_trust_timeseries_talk.png
#   figures/ch3_profess_trust_scatter_talk.png

if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, ggplot2, readr, patchwork, tibble, tidyr)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})  # portable project root: works via Rscript from anywhere, or falls back to
    # getwd() when sourced interactively (assumes ch3_pipeline_restored/ as cwd)
PROJECT <- .ROOT
OUT1 <- file.path(PROJECT, "figures/ch3_profess_trust_timeseries_talk.png")
OUT2 <- file.path(PROJECT, "figures/ch3_profess_trust_scatter_talk.png")

NAVY <- "#1F3864"; RED <- "#d7191c"; GREY <- "#607D8B"

# ============================================================
# 1. REBUILD PROFESSIONALISATION PC1 (same as 41e/41f)
# ============================================================
norm01 <- function(x) (x - min(x, na.rm=TRUE)) / (max(x, na.rm=TRUE) - min(x, na.rm=TRUE))
zscore <- function(x) (x - mean(x, na.rm=TRUE)) / sd(x, na.rm=TRUE)
YEARS  <- 1979:2025

career_obs <- bind_rows(
  tribble(~year,~pct, 1979,3.0, 1983,4.5, 2010,14.0, 2015,17.0, 2019,21.0),
  tribble(~year,~pct, 1987,5.4, 1992,7.3, 1997,9.5, 2001,10.5, 2005,14.1)
) |> arrange(year)

career_annual <- tibble(year = YEARS) |>
  mutate(obs_yr     = sapply(year, function(y) max(career_obs$year[career_obs$year <= y])),
         career_pct = career_obs$pct[match(obs_yr, career_obs$year)])

spads <- read_csv(file.path(PROJECT, "data/raw/spads_DATA_ENTRY.csv"),
                  show_col_types = FALSE) |> filter(year <= 2025)
spads_annual <- tibble(year = YEARS,
  n_spads = approx(spads$year, spads$n_spads, xout = YEARS, rule = 2)$y)

ipsa  <- read_csv(file.path(PROJECT,"data/processed/ipsa_staffing_annual.csv"),
                  show_col_types=FALSE) |> select(cal_year, staffing_real=mean_staffing_real_2015)
# REPOINTED 7 Sep 2026: Butler & Butler-calibrated real series, see 41m_staffing_calibrate_butler.R
pre10 <- read_csv(file.path(PROJECT,"data/processed/staffing_pre2010_calibrated_butler.csv"),
                  show_col_types=FALSE) |> filter(!is.na(real_2015_mean)) |>
  select(cal_year=year, staffing_real=real_2015_mean)
staffing_obs <- bind_rows(pre10, ipsa) |> arrange(cal_year) |> filter(cal_year <= 2025)
staffing_annual <- tibble(year = YEARS) |>
  mutate(obs_yr        = sapply(year, function(y) max(staffing_obs$cal_year[staffing_obs$cal_year <= y])),
         staffing_real = staffing_obs$staffing_real[match(obs_yr, staffing_obs$cal_year)])

d_prof <- tibble(year = YEARS) |>
  left_join(career_annual   |> select(year, career_pct),    by="year") |>
  left_join(spads_annual    |> select(year, n_spads),        by="year") |>
  left_join(staffing_annual |> select(year, staffing_real),  by="year") |>
  mutate(career_norm   = norm01(career_pct),
         spads_norm    = norm01(n_spads),
         staffing_norm = norm01(staffing_real))

pca_res <- prcomp(d_prof |> select(career_norm, spads_norm, staffing_norm),
                  scale. = TRUE, center = TRUE)
d_prof  <- d_prof |> mutate(prof_pc1 = pca_res$x[, 1])

cat("PC1 variance explained:", round(summary(pca_res)$importance[2,1]*100, 1), "%\n")

# ============================================================
# 2. LOAD TRUST DV
# ============================================================
trust <- read_csv(file.path(PROJECT, "data/processed/trust_extended_1979_2025.csv"),
                  show_col_types = FALSE) |>
  select(year, trust_pct, data_source, note) |>
  mutate(observed = !grepl("INTERPOLATED", data_source, fixed = TRUE))

cat("Trust series: N =", nrow(trust), "  range", min(trust$year), "-", max(trust$year), "\n")
cat("  of which observed (BSA):", sum(trust$observed),
    " calibrated (TrustGov/Ipsos):", sum(!trust$observed), "\n")

# ============================================================
# 3. MERGE WITH LAGS
# ============================================================
# Lag: professionalisation at year t-k paired with trust at year t
merged <- trust |>
  left_join(d_prof |> select(year, prof_pc1),                            by="year") |>
  left_join(d_prof |> select(year, prof_lag1=prof_pc1) |> mutate(year=year+1), by="year") |>
  left_join(d_prof |> select(year, prof_lag2=prof_pc1) |> mutate(year=year+2), by="year")

# Observed-only robustness check (BSA years only, drops calibrated years)
merged_obs <- merged |> filter(observed)

r_stats <- function(x, y) {
  cc  <- complete.cases(cbind(x, y))
  r   <- cor(x[cc], y[cc])
  n   <- sum(cc)
  tst <- r * sqrt((n-2)/(1-r^2))
  p   <- 2 * pt(-abs(tst), df=n-2)
  list(r=r, n=n, t=tst, p=p)
}

s0 <- r_stats(merged$trust_pct, merged$prof_pc1)
s1 <- r_stats(merged$trust_pct, merged$prof_lag1)
s2 <- r_stats(merged$trust_pct, merged$prof_lag2)

cat(sprintf("Lag 0: r=%.3f, N=%d, p=%.3f\n", s0$r, s0$n, s0$p))
cat(sprintf("Lag 1: r=%.3f, N=%d, p=%.3f\n", s1$r, s1$n, s1$p))
cat(sprintf("Lag 2: r=%.3f, N=%d, p=%.3f\n", s2$r, s2$n, s2$p))

s0_obs <- r_stats(merged_obs$trust_pct, merged_obs$prof_pc1)
s1_obs <- r_stats(merged_obs$trust_pct, merged_obs$prof_lag1)
s2_obs <- r_stats(merged_obs$trust_pct, merged_obs$prof_lag2)
cat("\n--- Robustness: BSA-observed years only (drops calibrated years) ---\n")
cat(sprintf("Lag 0: r=%.3f, N=%d, p=%.3f\n", s0_obs$r, s0_obs$n, s0_obs$p))
cat(sprintf("Lag 1: r=%.3f, N=%d, p=%.3f\n", s1_obs$r, s1_obs$n, s1_obs$p))
cat(sprintf("Lag 2: r=%.3f, N=%d, p=%.3f\n", s2_obs$r, s2_obs$n, s2_obs$p))

