# ============================================================
# FIGURE 2: THREE SCATTER PLOTS
# ============================================================
make_scatter <- function(x_vec, y_vec, obs_vec, stats, lag_label, x_label) {
  df     <- data.frame(x=x_vec, y=y_vec, observed=obs_vec) |> na.omit()
  p_str  <- if(stats$p < 0.001) "p < .001" else sprintf("p = %.3f", stats$p)
  annot  <- sprintf("r = %.3f\n%s\nN = %d", stats$r, p_str, stats$n)

  ggplot(df, aes(x=x, y=y)) +
    geom_smooth(method="lm", se=TRUE, colour=RED, fill="#ffd5d5",
                linewidth=1.0, alpha=0.35) +
    geom_point(aes(shape=observed), colour=NAVY, size=3, alpha=0.85) +
    scale_shape_manual(values = c("TRUE" = 16, "FALSE" = 1), guide = "none") +
    annotate("label", x=-Inf, y=Inf,
             label    = annot,
             hjust    = -0.1, vjust=1.15,
             size     = 3.5, colour=NAVY, fill="white",
             fontface = "bold", lineheight=1.4) +
    labs(
      title = lag_label,
      x     = x_label,
      y     = "Political trust %"
    ) +
    theme_bw(base_size=11) +
    theme(
      plot.title       = element_text(face="bold", colour=NAVY, size=11),
      panel.grid.minor = element_blank()
    )
}

p_s0 <- make_scatter(merged$prof_pc1,  merged$trust_pct, merged$observed, s0,
  "Lag 0 — same year", "Professionalisation PC1 (year t)")
p_s1 <- make_scatter(merged$prof_lag1, merged$trust_pct, merged$observed, s1,
  "Lag 1 — IV leads by 1 year", "Professionalisation PC1 (year t-1)")
p_s2 <- make_scatter(merged$prof_lag2, merged$trust_pct, merged$observed, s2,
  "Lag 2 — IV leads by 2 years", "Professionalisation PC1 (year t-2)")

best_lag <- which.max(abs(c(s0$r, s1$r, s2$r))) - 1
best_r   <- c(s0$r, s1$r, s2$r)[best_lag + 1]
best_p   <- c(s0$p, s1$p, s2$p)[best_lag + 1]
best_n   <- c(s0$n, s1$n, s2$n)[best_lag + 1]

p_scatter <- (p_s0 | p_s1 | p_s2) +
  plot_annotation(
    title    = "Professionalisation and political trust: lagged correlations",
    subtitle = paste0(
      sprintf("Each point = one year, 1979-2025 (N = %d to %d across lags). Filled = BSA-observed; ", min(s0$n, s1$n, s2$n), max(s0$n, s1$n, s2$n)),
      "hollow = calibrated (TrustGov/Ipsos).\n",
      sprintf("Strongest lag: %d (r = %.3f, p = %.3f). BSA-only robustness: lag %d r = %.3f (N = %d, p = %.3f).\n",
              best_lag, best_r, best_p, best_lag,
              c(s0_obs$r, s1_obs$r, s2_obs$r)[best_lag + 1],
              c(s0_obs$n, s1_obs$n, s2_obs$n)[best_lag + 1],
